extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var rock := await instantiate_scene("res://rock.tscn")
	if not check("rock_loaded", rock != null, "La scena rock.tscn deve caricarsi correttamente"):
		return
	check("const_pos", rock.get("START_POSITION") == Vector2(200, 80), "La costante START_POSITION deve valere Vector2(200, 80)")
	check("const_dmg", rock.get("MAX_DAMAGE") == 3, "La costante MAX_DAMAGE deve valere 3")
	var name_val = get_prop(rock, "obstacle_name")
	check("var_name", name_val == "Roccia" and typeof(name_val) == TYPE_STRING, "La variabile obstacle_name deve essere String con valore 'Roccia'")
	var speed_val = get_prop(rock, "fall_speed")
	check("var_speed", speed_val == 240.0 and typeof(speed_val) == TYPE_FLOAT, "La variabile fall_speed deve essere float con valore 240.0")
	var dmg_val = get_prop(rock, "damage")
	check("var_dmg", dmg_val == 1 and typeof(dmg_val) == TYPE_INT, "La variabile damage deve essere int con valore 1")
	var act_val = get_prop(rock, "is_active")
	check("var_act", act_val == true and typeof(act_val) == TYPE_BOOL, "La variabile is_active deve essere bool con valore true")
	var ratio_val = get_prop(rock, "danger_ratio")
	check("var_ratio", typeof(ratio_val) == TYPE_FLOAT and absf(ratio_val - (1.0 / 3.0)) < 0.01, "danger_ratio deve essere float calcolato con conversione decimale (circa 0.333)")
	check("rock_pos", rock.position == Vector2(240, 80), "La posizione della roccia deve avere x incrementata di 40.0 (Vector2(240, 80))")
	check("rock_color", rock.modulate == Color.RED, "Il modulate della roccia deve essere Color.RED")
